equation_logic_text:
// Logic template
var calc_output = [];

var age = parseFloat(age);
var wbc = parseFloat(wbc);
var crcl = parseFloat(crcl);
var bled = parseFloat(bled);

if (UOMSYSTEM == true) { 
    var hb = parseFloat(hb);
}
if (UOMSYSTEM == false) {
    var hb = parseFloat(hb)/10;
}

// Hb: 10–12 g/dL
if (hb < 10) hb = 10;
else if (hb > 12) hb = 12;

// Age: 50–90 years
if (age < 50) age = 50;
else if (age > 90) age = 90;

// WBC: 5–20 (10^3/µL)
if (wbc < 5) wbc = 5;
else if (wbc > 20) wbc = 20;


// CrCl: cap at 100 only (no lower clamp)
if (crcl > 100) {
  crcl = 100;
}

// calculate score
var ln = 0.02595618 * age  + (-0.0140439) * crcl + 0.05697497 * wbc + (-0.40551264) * hb + 1.41955653 * bled;
var score_raw = 100 * (ln + 4.68785783) / 5.52784356;
var score = Math.round(score_raw);

// risk cutoffs
var risk;
if (score <= 10) {
  risk = 'Very low';
} else if (score >= 11 && score <= 17) {
  risk = 'Low';
} else if (score >= 18 && score <= 24) {
  risk = 'Moderate';
} else {
  risk = 'High';
}

// calculate % risks
var timi_major = (1 - Math.exp(-0.001874968 * Math.exp(score * 0.06687003))) * 100;
var timi_major_minor = (1 - Math.exp(-0.002871235 * Math.exp(score * 0.0747252))) * 100;

if (timi_major > 2.06) {
  timi_major = '>2.06';
} else {
  timi_major = timi_major.toFixed(1);
}

if (timi_major_minor > 4.14) {
  timi_major_minor = '>4.14';
} else {
  timi_major_minor = timi_major_minor.toFixed(1);
}

// Output
calc_output.push({
    name: 'mini',
    value: score,
    value_text: 'points',
    message: risk + ' risk'
});
calc_output.push({
    name: '10641_PRECISE-DAPT Score_result',
    value: score,
    value_text: 'points',
    message: 'PRECISE-DAPT Score'
});
calc_output.push({
    name: '10641_PRECISE-DAPT Score_interpretation',
    value: risk,
    value_text: 'risk',
    message: '12-months TIMI major or minor bleeding risk: ' + timi_major_minor + '%<br/>12-months TIMI major bleeding risk: ' + timi_major + '%'
});
